import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import * as ort from "onnxruntime-node";
import { convertToFp32, splitsToSlices } from "../src/engine/onnxRewrite";

// Generated by tests/fixtures/make-fp16-model.py.
const fp16 = new Uint8Array(readFileSync(new URL("./fixtures/tiny-fp16.onnx", import.meta.url)));

async function run(model: Uint8Array, data: Float32Array) {
  const session = await ort.InferenceSession.create(model);
  const outputs = await session.run({ data: new ort.Tensor("float32", data, [1, 2, 2, 2]) });
  return { value: Array.from(outputs.value.data as Float32Array), special: Array.from(outputs.special.data as Float32Array) };
}

describe("convertToFp32", () => {
  it("converts initializers, attribute tensors, value infos and casts", () => {
    const result = convertToFp32(fp16);
    // weight (raw_data), bias (int32_data), two Constant tensors, sum16's value info, one Cast.
    expect(result.converted).toBe(6);
    expect(convertToFp32(result.model).converted).toBe(0);
  });

  it("reports the graph's inputs and outputs", () => {
    const result = convertToFp32(fp16);
    expect(result.inputs).toEqual([{ name: "data", elemType: 1, dims: [null, 2, 2, 2] }]);
    expect(result.outputs.map((o) => o.name)).toEqual(["value", "special"]);
  });

  it("returns FP32 networks unchanged", () => {
    const fp32 = convertToFp32(fp16).model;
    expect(convertToFp32(fp32).model).toBe(fp32);
  });

  it("computes the same results as the FP16 network", async () => {
    const data = Float32Array.from([1, 2, 3, 4, -1, 0, 2, 8]);
    const converted = await run(convertToFp32(fp16).model, data);
    // 0.5 * channel 0 - 1.25 * channel 1 + bias 2 + offset 0.25
    expect(converted.value).toEqual([4, 3.25, 1.25, -5.75]);
    expect(converted).toEqual(await run(fp16, data));
  });

  it("converts subnormal and special half values exactly", async () => {
    const { special } = await run(convertToFp32(fp16).model, new Float32Array(8));
    expect(special.slice(0, 5)).toEqual([2 ** -24, 2 ** -15, 65504, -0, Infinity]);
    expect(Object.is(special[3], -0)).toBe(true);
    expect(special[5]).toBe(-3);
  });

  it("rejects files that are not ONNX models", () => {
    expect(() => convertToFp32(new Uint8Array([0x0a, 0x05, 0x01]))).toThrow();
  });
});

describe("splitsToSlices", () => {
  // The bundled FP32 copy of the real network, which has two Split nodes.
  const network = new Uint8Array(readFileSync(new URL("../public/engine/twin-s.onnx", import.meta.url)));

  it("replaces each Split with Slices that compute the same outputs", async () => {
    const { model, replaced } = splitsToSlices(network);
    expect(replaced).toBe(2);
    expect(splitsToSlices(model).replaced).toBe(0);
    const batch = 4;
    // Sparse 0/1 planes, like encoded positions.
    const data = Float32Array.from({ length: batch * 78 * 64 }, (_, i) => ((i * 2654435761) % 97 < 9 ? 1 : 0));
    const run = async (bytes: Uint8Array) => {
      const session = await ort.InferenceSession.create(bytes, { logSeverityLevel: 3 });
      const outputs = await session.run({ data: new ort.Tensor("float32", data, [batch, 78, 8, 8]) });
      return session.outputNames.map((name) => Array.from(outputs[name].data as Float32Array));
    };
    expect(await run(model)).toEqual(await run(network));
  });

  it("leaves networks without Split nodes unchanged", () => {
    const fp32 = convertToFp32(fp16).model;
    expect(splitsToSlices(fp32)).toEqual({ model: fp32, replaced: 0 });
  });
});
